import {language,t} from './i18n.js?v=d15eb85b2d2d';
import {universitySupportCopy} from './university-support-copy.js?v=d15eb85b2d2d';
const $=id=>document.getElementById(id);
const tr=key=>universitySupportCopy[key]?.[language==='zh'?1:0]??t(key);
const make=(tag,cls,value)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(value!==undefined)e.textContent=value;return e;};
const link=(url,value)=>{const a=make('a','',value);a.href=url;a.target='_blank';a.rel='noopener noreferrer';return a;};
const today=()=>new Date().toISOString().slice(0,10);
const fields={title:120,office:180,summary:800,request:1000,expect:800,template:2000};

export function initUniversitySupport({state,api,run,button,toast,requireMember,confirm}){
 let entries=[],more=false,loaded=false,loading=false,publicRequest=0,errorKey=null,needsApply=false;
 let mine=[],mineMore=false,mineLoaded=false,mineLoading=false,review=[],reviewMore=false,adminEntries=[],adminMore=false,adminLoaded=false,adminLoading=false;
 let epoch=0,memberRequest=0,adminRequest=0,knownMember=state.profile?.id??null,knownModerator=!!state.moderator,suggestionTarget=null,editId=null,editorDirty=false,sending=false,saving=false;
 const templates=new Map(),reviewNotes=new Map(),filterIds=['support-university','support-query','support-audience','support-category'];
 const active=()=>state.view==='resources'&&!$('support-pane').hidden;
 const member=()=>state.profile?.id??null;
 const fingerprint=()=>JSON.stringify(filterIds.map(id=>$(id).value.trim()));
 const privateValid=(who,generation)=>member()===who&&generation===epoch;
 const moderator=()=>!!state.profile&&state.moderator;
 const action=(key,handler,cls='secondary')=>{const b=button(key,handler,cls);b.textContent=tr(key);return b;};
 function translatePane(){for(const e of $('support-pane').querySelectorAll('[data-i18n]'))e.textContent=tr(e.dataset.i18n);for(const e of $('support-pane').querySelectorAll('[data-placeholder]'))e.placeholder=tr(e.dataset.placeholder);}
 function params(){const p=new URLSearchParams();for(const [id,key] of [['support-university','university'],['support-query','q'],['support-audience','audience'],['support-category','category']])if($(id).value.trim())p.set(key,$(id).value.trim());p.set('limit','12');return p;}
 function renderMembership(){
  $('support-suggestion-fields').disabled=!member()||sending;$('support-member-area').hidden=!member();$('support-join').hidden=!!member();$('support-join-button').hidden=!!member();
  $('support-join').textContent=tr(state.signedIn?'finishOnboarding':'supportSuggestJoin');$('support-join-button').textContent=tr(state.signedIn?'finishOnboarding':'signIn');
  $('support-admin').hidden=!moderator();$('support-admin-fields').disabled=!moderator()||saving;$('support-admin-save').disabled=!moderator()||saving;$('support-source-checked').disabled=!moderator()||saving;
  $('support-search').disabled=loading;$('support-refresh').disabled=loading;$('support-more').disabled=loading;$('support-more').hidden=!more||needsApply;
  $('support-filter-notice').hidden=!needsApply;$('support-feed').setAttribute('aria-busy',String(loading));
  $('support-suggestions-refresh').disabled=mineLoading||!member();$('support-suggestions-more').disabled=mineLoading;$('support-suggestions-more').hidden=!mineMore;
  $('support-admin-refresh').disabled=adminLoading||!moderator();$('support-admin-more').disabled=adminLoading;$('support-admin-more').hidden=!adminMore;$('support-review-more').disabled=adminLoading;$('support-review-more').hidden=!reviewMore;
  $('support-error').hidden=!errorKey;$('support-error').textContent=errorKey?tr(errorKey):'';
  $('support-suggestion-new').hidden=!suggestionTarget;$('support-suggestion-target').hidden=!suggestionTarget;$('support-suggestion-target').textContent=suggestionTarget?tr('supportSuggestionTarget')+': '+suggestionTarget[language].title:'';
  $('support-admin-date').max=today();
 }
 function fact(dl,key,value){const row=make('div');row.append(make('dt','',tr(key)),make('dd','',value));dl.append(row);}
 function renderDirectory(){
  const box=$('support-feed');box.replaceChildren();
  if(!entries.length){const empty=make('div','support-empty');empty.append(make('p','',tr(loading?'supportLoading':'supportEmpty')));if(!loading)empty.append(make('p','small',tr('supportNoAutoUniversity')));box.append(empty);}
  for(const s of entries){const c=s[language],card=make('article','panel support-card'),meta=make('div','support-card-meta');meta.append(make('span','chip',s.university[language]),make('span','chip',tr('supportAudience_'+s.audience)),make('span','chip',tr('supportCategory_'+s.category)));card.append(meta,make('h3','',c.title),make('p','',c.summary));
   const dl=make('dl','support-facts');fact(dl,'supportOffice',c.office);fact(dl,'supportRequest',c.request);fact(dl,'supportExpect',c.expect);card.append(dl);
   const source=make('div','support-source');source.append(link(s.sourceUrl,tr('supportOfficialSource')),make('span','',tr('supportChecked')+': '+s.checkedDate));if(s.email)source.append(link('mailto:'+s.email,tr('supportEmail')+': '+s.email));card.append(source);
   const key=s.id+':'+language,details=make('details'),summary=make('summary','',tr('supportTemplate')),note=make('p','small',tr('supportTemplateNote')),editor=make('textarea');editor.rows=9;editor.maxLength=2000;editor.value=templates.get(key)??c.template;editor.setAttribute('aria-label',tr('supportTemplate')+' · '+c.title);editor.oninput=()=>templates.set(key,editor.value);
   const actions=make('div','resource-actions');actions.append(action('supportTemplateCopy',async()=>{try{await navigator.clipboard.writeText(editor.value);toast('supportTemplateCopied');}catch{editor.focus();editor.select();toast('copyManually');}}),action('supportTemplateReset',()=>confirm('supportTemplateResetConfirm',()=>{templates.delete(key);editor.value=c.template;}),'text-button'));details.append(summary,note,editor,actions);card.append(details);
   const correction=make('div','resource-actions');correction.append(action('supportCorrection',()=>{if(!requireMember())return;const apply=()=>{$('support-suggestion-form').reset();suggestionTarget=s;$('support-suggestion-university').value=s.university[language];$('support-suggestion-source').value=s.sourceUrl;renderMembership();$('support-suggestion-note').focus();};if($('support-suggestion-note').value.trim())confirm('supportAdminCancelConfirm',apply);else apply();},'text-button'));card.append(correction);box.append(card);
  }
 }
 function suggestionCard(s,reviewing=false){
  const card=make('article','support-suggestion-card'+(reviewing?' support-review-card':'')),head=make('div','support-card-meta');head.append(make('strong','',s.university),make('span','chip',tr('supportStatus_'+s.status)));card.append(head,link(s.sourceUrl,tr('supportOfficialSource')),make('p','',s.note));
  if(s.moderatorNote)card.append(make('p','small',tr('supportModeratorNote')+': '+s.moderatorNote));
  if(reviewing){card.append(make('p','small',tr('supportReviewAuthor')+': '+s.authorId));const note=make('textarea');note.rows=3;note.maxLength=1000;note.placeholder=tr('supportModeratorNote');note.setAttribute('aria-label',tr('supportModeratorNote')+' · '+s.university);note.value=reviewNotes.get(s.id)??'';note.oninput=()=>reviewNotes.set(s.id,note.value);card.append(note);const actions=make('div','resource-actions');for(const [key,status]of [['supportReviewDone','reviewed'],['supportReviewReject','rejected']])actions.append(action(key,async()=>{if(!moderator())return;const who=member(),generation=epoch;await api('/university-support/suggestions/'+s.id,'PUT',{status,moderatorNote:note.value});if(!privateValid(who,generation)||!moderator())return;reviewNotes.delete(s.id);adminRequest++;adminLoading=false;await loadAdmin();mineLoaded=false;memberRequest++;mineLoading=false;await loadMine();toast('supportReviewSaved');}));card.append(actions);}
  return card;
 }
 function renderPrivate(){const box=$('support-my-suggestions');box.replaceChildren();if(member()){if(!mine.length)box.append(make('p','small',tr(mineLoading?'loading':'supportNoSuggestions')));for(const s of mine)box.append(suggestionCard(s));}
  const manager=$('support-admin-list'),queue=$('support-review-list');manager.replaceChildren();queue.replaceChildren();if(!moderator())return;
  for(const s of adminEntries){const row=make('article','support-manager-row');row.append(make('h4','',s[language].title),make('p','small',s.university[language]+' · '+tr(s.archived?'supportAdminArchived':'supportAdminActive')),make('p','small',tr('supportChecked')+': '+s.checkedDate));const actions=make('div','resource-actions');actions.append(action('supportAdminEdit',()=>{const edit=()=>fillEditor(s);if(editorDirty)confirm('supportAdminCancelConfirm',edit);else edit();}));if(!s.archived)actions.append(action('supportAdminArchive',()=>confirm('supportAdminArchiveConfirm',async()=>{if(!moderator())return;const who=member(),generation=epoch;await api('/university-support/admin/'+s.id,'DELETE');if(!privateValid(who,generation)||!moderator())return;await reloadDirectoryAndAdmin();toast('supportAdminArchivedToast');}),'text-button'));row.append(actions);manager.append(row);}
  if(!review.length)queue.append(make('p','small',tr(adminLoading?'loading':'supportReviewEmpty')));for(const s of review)queue.append(suggestionCard(s,true));
 }
 async function loadDirectory(append=false){
  if(loading)return;const request=++publicRequest,filters=fingerprint(),p=params();if(append)p.set('offset',String(entries.length));loading=true;errorKey=null;renderMembership();if(!entries.length)renderDirectory();
  try{const result=await api('/university-support?'+p);if(request!==publicRequest||filters!==fingerprint())return;entries=append?[...entries,...result.services]:result.services;more=result.hasMore;loaded=true;needsApply=false;renderDirectory();}catch(e){if(request!==publicRequest||e.message==='requestCanceled')return;errorKey=e.message||'supportLoadError';throw e;}finally{if(request===publicRequest){loading=false;renderMembership();}}
 }
 async function reloadDirectoryAndAdmin(){publicRequest++;loading=false;adminRequest++;adminLoading=false;await Promise.all([loadDirectory(),loadAdmin()]);}
 async function loadMine(append=false){
  if(!member()||mineLoading)return;const who=member(),generation=epoch,request=++memberRequest;mineLoading=true;renderMembership();
  try{const result=await api('/university-support/suggestions?limit=20'+(append?'&offset='+mine.length:''));if(!privateValid(who,generation)||request!==memberRequest)return;mine=append?[...mine,...result.suggestions]:result.suggestions;mineMore=result.hasMore;mineLoaded=true;renderPrivate();}finally{if(request===memberRequest){mineLoading=false;renderMembership();}}
 }
 async function loadAdmin(appendKind=''){
  if(!moderator()||adminLoading)return;const who=member(),generation=epoch,request=++adminRequest;adminLoading=true;renderMembership();
  try{const [services,suggestions]=await Promise.all([appendKind==='review'?Promise.resolve(null):api('/university-support/admin?archived=1&limit=20'+(appendKind==='services'?'&offset='+adminEntries.length:'')),appendKind==='services'?Promise.resolve(null):api('/university-support/suggestions?review=1&limit=20'+(appendKind==='review'?'&offset='+review.length:''))]);if(!privateValid(who,generation)||!moderator()||request!==adminRequest)return;if(services){adminEntries=appendKind==='services'?[...adminEntries,...services.services]:services.services;adminMore=services.hasMore;}if(suggestions){review=appendKind==='review'?[...review,...suggestions.suggestions]:suggestions.suggestions;reviewMore=suggestions.hasMore;}adminLoaded=true;renderPrivate();}finally{if(request===adminRequest){adminLoading=false;renderMembership();}}
 }
 function editorInput(container,id,labelKey,type='text',max=120,options){const box=make('div'),label=make('label','',tr(labelKey));label.htmlFor=id;label.dataset.i18n=labelKey;const input=make(type==='textarea'?'textarea':type==='select'?'select':'input');input.id=id;if(type==='textarea'){input.rows=max>=800?4:2;input.maxLength=max;}else if(type==='select'){for(const [value,key]of options){const o=make('option','',tr(key));o.value=value;o.dataset.i18n=key;input.append(o);}}else{input.type=type;if(type!=='date')input.maxLength=max;}input.required=id!=='support-admin-email';box.append(label,input);container.append(box);}
 function buildEditor(){const root=$('support-admin-fields'),grid=make('div','support-admin-grid');editorInput(grid,'support-admin-uni-en','supportAdminUniEn');editorInput(grid,'support-admin-uni-zh','supportAdminUniZh');editorInput(grid,'support-admin-audience','supportAudience','select',0,['students','staff','both'].map(x=>[x,'supportAudience_'+x]));editorInput(grid,'support-admin-category','supportCategory','select',0,['accessibility','wellbeing','study','staff'].map(x=>[x,'supportCategory_'+x]));editorInput(grid,'support-admin-source','supportSuggestionSource','url',2048);editorInput(grid,'support-admin-date','supportChecked','date');editorInput(grid,'support-admin-email','supportEmail','email',254);editorInput(grid,'support-admin-visibility','supportAdminVisibility','select',0,[['active','supportAdminActive'],['archived','supportAdminArchived']]);root.append(grid);for(const lang of ['en','zh']){const section=make('div','support-admin-copy'),heading=make('h4','',tr(lang==='en'?'supportAdminEnglish':'supportAdminChinese'));heading.dataset.i18n=lang==='en'?'supportAdminEnglish':'supportAdminChinese';section.append(heading);for(const [key,max]of Object.entries(fields))editorInput(section,'support-admin-'+lang+'-'+key,'supportField_'+key,max>200?'textarea':'text',max);root.append(section);}resetEditor();}
 function resetEditor(){$('support-admin-form').reset();editId=null;editorDirty=false;$('support-admin-date').value=today();$('support-admin-date').max=today();}
 function fillEditor(s){editId=s.id;editorDirty=false;$('support-admin-uni-en').value=s.university.en;$('support-admin-uni-zh').value=s.university.zh;for(const key of ['audience','category'])$('support-admin-'+key).value=s[key];$('support-admin-source').value=s.sourceUrl;$('support-admin-date').value=s.checkedDate;$('support-admin-email').value=s.email;$('support-admin-visibility').value=s.archived?'archived':'active';$('support-source-checked').checked=false;for(const lang of ['en','zh'])for(const key of Object.keys(fields))$('support-admin-'+lang+'-'+key).value=s[lang][key];$('support-admin-uni-en').focus();}
 function editorValue(){const input={university:{en:$('support-admin-uni-en').value,zh:$('support-admin-uni-zh').value},sourceUrl:$('support-admin-source').value,checkedDate:$('support-admin-date').value,email:$('support-admin-email').value,sourceChecked:$('support-source-checked').checked,archived:$('support-admin-visibility').value==='archived'};for(const key of ['audience','category'])input[key]=$('support-admin-'+key).value;for(const lang of ['en','zh']){input[lang]={};for(const key of Object.keys(fields))input[lang][key]=$('support-admin-'+lang+'-'+key).value;}return input;}
 function render(){translatePane();renderMembership();renderDirectory();renderPrivate();}
 function resetMembers(){epoch++;memberRequest++;adminRequest++;mineLoading=false;adminLoading=false;sending=false;saving=false;mine=[];review=[];adminEntries=[];mineMore=false;reviewMore=false;adminMore=false;mineLoaded=false;adminLoaded=false;suggestionTarget=null;templates.clear();reviewNotes.clear();$('support-suggestion-form').reset();resetEditor();$('support-admin').open=false;knownMember=null;knownModerator=false;render();}
 function memberChanged(){const who=member();if(who!==knownMember||(!state.moderator&&knownModerator)){resetMembers();knownMember=who;}knownModerator=!!state.moderator;renderMembership();if(active()){if(!loaded&&!loading&&!needsApply)run($('support-refresh'),()=>loadDirectory());if(who&&!mineLoaded&&!mineLoading)run($('support-suggestions-refresh'),()=>loadMine());if(moderator()&&$('support-admin').open&&!adminLoaded&&!adminLoading)run($('support-admin-refresh'),()=>loadAdmin());}}
 function invalidate(){publicRequest++;loading=false;loaded=false;entries=[];more=false;errorKey=null;mineLoaded=false;adminLoaded=false;render();memberChanged();}
 buildEditor();
 $('support-filter-form').onsubmit=e=>{e.preventDefault();run($('support-search'),()=>loadDirectory());};$('support-refresh').onclick=()=>run($('support-refresh'),()=>loadDirectory());$('support-more').onclick=()=>run($('support-more'),()=>loadDirectory(true));
 for(const id of filterIds)$(id).addEventListener('input',()=>{needsApply=true;renderMembership();});
 $('support-join-button').onclick=()=>requireMember();$('support-suggestions-refresh').onclick=()=>run($('support-suggestions-refresh'),()=>loadMine());$('support-suggestions-more').onclick=()=>run($('support-suggestions-more'),()=>loadMine(true));
 $('support-suggestion-new').onclick=()=>confirm('supportAdminCancelConfirm',()=>{suggestionTarget=null;$('support-suggestion-form').reset();renderMembership();});
 $('support-suggestion-form').onsubmit=e=>{e.preventDefault();run($('support-suggestion-submit'),async()=>{if(!requireMember()||sending)return;const who=member(),generation=epoch;const value={university:$('support-suggestion-university').value,sourceUrl:$('support-suggestion-source').value,note:$('support-suggestion-note').value,serviceId:suggestionTarget?.id??null};sending=true;renderMembership();try{await api('/university-support/suggestions','POST',value);if(!privateValid(who,generation))return;$('support-suggestion-form').reset();suggestionTarget=null;mineLoaded=false;memberRequest++;mineLoading=false;await loadMine();toast('supportSuggestionSent');}finally{if(privateValid(who,generation)){sending=false;renderMembership();}}});};
 $('support-admin').ontoggle=()=>{if($('support-admin').open&&moderator()&&!adminLoaded&&!adminLoading)run($('support-admin-refresh'),()=>loadAdmin());};$('support-admin-refresh').onclick=()=>run($('support-admin-refresh'),()=>loadAdmin());$('support-admin-more').onclick=()=>run($('support-admin-more'),()=>loadAdmin('services'));$('support-review-more').onclick=()=>run($('support-review-more'),()=>loadAdmin('review'));
 $('support-admin-new').onclick=$('support-admin-clear').onclick=()=>{if(editorDirty)confirm('supportAdminCancelConfirm',resetEditor);else resetEditor();};$('support-admin-form').oninput=()=>{editorDirty=true;};
 $('support-admin-form').onsubmit=e=>{e.preventDefault();run($('support-admin-save'),async()=>{if(!moderator()||saving)return;const who=member(),generation=epoch,value=editorValue(),path='/university-support/admin'+(editId?'/'+editId:''),method=editId?'PUT':'POST';saving=true;renderMembership();try{await api(path,method,value);if(!privateValid(who,generation)||!moderator())return;resetEditor();await reloadDirectoryAndAdmin();toast('supportAdminSaved');}finally{if(privateValid(who,generation)){saving=false;renderMembership();}}});};
 render();return {render,memberChanged,resetMembers,invalidate};
}
